const o={getName(){return"foxnews"},async getTab(){const[t]=await chrome.tabs.query({active:!0,currentWindow:!0});return t},async getHTML(){const t=await this.getTab();return(await chrome.scripting.executeScript({target:{tabId:t.id},func:()=>document.documentElement.outerHTML}))[0].result},async getPostAuthor(){const t=await this.getHTML();let e="";return e=$(t).find("div.author-byline").clone().find(".article-source").remove().end().text(),e=e.replace("By",""),e.trim()},async getPostTitle(){const t=await this.getHTML();return $(t).find("h1.headline").first().text().trim()},async getPostContent(){const t=await this.getHTML();let e="";return $(t).find("div.article-body").find("p").each((n,s)=>{let r=$(s).text();e+=`<p>${r}</p>`}),e},async getPageContent(){return{author:await this.getPostAuthor(),title:await this.getPostTitle(),postContent:await this.getPostContent()}},async generateContentHTML(t){const e=t.author,n=t.title,s=t.postContent;let r=`<p class="fs-2">${n}</p>`;return r+=`<p class="fs-5 fw-bold">By: ${e}</p>`,r+=`<p class="fs-6 ttsoc-read-more">${s}</p>`,r},buildSelectedContent(t,e=[]){let n={};if(t===void 0)return;const s=$("<div>").html(t.postContent).text();return n.postContent=s,n.title=t.title,n.author=t.author,n}};export{o as default};
